// The company this mailbox belongs to: paste its id below in each copy (or set DP_INBOX_ORG when there is one mailbox).
const ORG = $env.DP_INBOX_ORG || 'PASTE-COMPANY-ID';
const out = [];
for (const it of $input.all()) {
  const e = it.json; const from = String(e.from || ''); const subject = String(e.subject || '');
  const text = String(e.textPlain || e.text || '').replace(/\r/g, '');
  const addr = (from.match(/[^\s<>"]+@[^\s<>"]+\.[^\s<>"]+/) || [''])[0].toLowerCase();
  const name = from.replace(/<[^>]*>/, '').replace(/"/g, '').trim();
  if (/mailer-daemon|postmaster/i.test(addr) || /undeliver|delivery status notification|returned mail|failure notice|delivery has failed|address not found/i.test(subject)) {
    const m = text.match(/Final-Recipient:[^;]*;\s*([^\s<>]+@[^\s<>]+)/i) || text.match(/(?:to|address)[^@\n]{0,40}?<?([^\s<>"]+@[^\s<>"]+\.[a-z]{2,})>?/i);
    if (m) out.push({ json: { payload: { type: 'bounce', organization_id: ORG, email: m[1].toLowerCase().replace(/[.,;]+$/, '') } } });
    continue;
  }
  if (!addr || /out of office|automatic reply|auto.?reply|away from/i.test(subject) || /^(no-?reply|noreply)@/.test(addr)) continue; // auto-replies don't stop campaigns
  const body = text.split(/\nOn .{0,200}wrote:|\n-{2,}\s*Original Message|\nFrom: /i)[0].split('\n').filter((l) => !l.startsWith('>')).join('\n').trim();
  out.push({ json: { reply_subject: /^re:/i.test(subject) ? subject : `Re: ${subject}`.slice(0, 200), payload: { type: 'message', organization_id: ORG, channel: 'email', from: addr, ...(name && name !== addr ? { name: name.slice(0, 200) } : {}), text: (body || subject).slice(0, 4000) } } });
}
return out;

// Signs one message for the OS inbound endpoint, exactly as the OS signs its webhooks.
const crypto = require('crypto');
const body = JSON.stringify($json.payload);
const ts = Math.floor(Date.now() / 1000);
const nonce = crypto.randomBytes(16).toString('hex');
const signature = crypto.createHmac('sha256', $env.DP_SIGNING_SECRET).update(`${ts}.${nonce}.${body}`).digest('hex');
return { json: { body, ts: String(ts), nonce, signature } };

// The OS returns auto_reply when the AI assistant answered; send it from this mailbox, in the same thread.
const src = $('Map to OS').all();
return $input.all().map((i, n) => (i.json && i.json.auto_reply ? { json: { ...i.json.auto_reply, subject: (src[n] && src[n].json.reply_subject) || i.json.auto_reply.subject } } : null)).filter(Boolean);
